package com.casecraft.model;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="timeline_events") public class TimelineEvent { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="case_id",nullable=false) private CaseFile caseFile; private LocalDateTime occurredAt; private String location; @Column(length=2000) private String description; public UUID getId(){return id;} public CaseFile getCaseFile(){return caseFile;} public void setCaseFile(CaseFile c){caseFile=c;} public LocalDateTime getOccurredAt(){return occurredAt;} public void setOccurredAt(LocalDateTime v){occurredAt=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} }
